// Generates every file that defines the Hummingbird app from
// Apps/AppManifest.swift. Run through scripts/generate-app:
//
//   scripts/generate-app           write the generated files
//   scripts/generate-app --check   exit 1 if any is out of date
import Foundation

// MARK: - Manifest model

/// A property-list value, written with Swift literals in the manifest.
enum PlistValue: Sendable, ExpressibleByStringLiteral, ExpressibleByBooleanLiteral, ExpressibleByIntegerLiteral,
    ExpressibleByArrayLiteral, ExpressibleByDictionaryLiteral {
    case string(String), bool(Bool), integer(Int), array([PlistValue]), dictionary([String: PlistValue])

    init(stringLiteral value: String) { self = .string(value) }
    init(booleanLiteral value: Bool) { self = .bool(value) }
    init(integerLiteral value: Int) { self = .integer(value) }
    init(arrayLiteral elements: PlistValue...) { self = .array(elements) }
    init(dictionaryLiteral elements: (String, PlistValue)...) {
        self = .dictionary(Dictionary(uniqueKeysWithValues: elements))
    }

    var object: Any {
        switch self {
        case .string(let value): value
        case .bool(let value): value
        case .integer(let value): value
        case .array(let values): values.map(\.object)
        case .dictionary(let values): values.mapValues(\.object)
        }
    }
}

/// A macOS sandbox entitlement: its key, and the Xcode setting that adds it.
enum SandboxEntitlement: CaseIterable, Sendable {
    case appSandbox, outgoingNetwork, incomingNetwork, camera

    var key: String {
        switch self {
        case .appSandbox: "com.apple.security.app-sandbox"
        case .outgoingNetwork: "com.apple.security.network.client"
        case .incomingNetwork: "com.apple.security.network.server"
        case .camera: "com.apple.security.device.camera"
        }
    }

    var xcodeSetting: String {
        switch self {
        case .appSandbox: "ENABLE_APP_SANDBOX"
        case .outgoingNetwork: "ENABLE_OUTGOING_NETWORK_CONNECTIONS"
        case .incomingNetwork: "ENABLE_INCOMING_NETWORK_CONNECTIONS"
        case .camera: "ENABLE_RESOURCE_ACCESS_CAMERA"
        }
    }
}

struct AppManifest: Sendable {
    let name: String
    let bundleID: String
    let version: String
    let build: String
    let developmentTeam: String
    let sources: String
    let icon: String
    let resources: [String]
    let info: [String: PlistValue]
    let sandbox: [SandboxEntitlement]
    let teamEntitlements: [String: PlistValue]
    let xcodeSettings: [(String, String)]
}

// MARK: - Outputs

let marker = "GENERATED by scripts/generate-app from Apps/AppManifest.swift; do not edit"

extension AppManifest {
    /// The Xcode app target's name: internal only, and never the app's name.
    /// xtool needs a package product named after the app, and xcodebuild
    /// resolves a name shared by a target and a package product to the
    /// product, so the app under test would be the library and UI tests
    /// couldn't start. The target still builds `name`.app: PRODUCT_NAME,
    /// the bundle, executable and CFBundleName are all `name`, and the
    /// schemes keep the app's name.
    var xcodeTarget: String { "\(name)-App" }

    var infoPath: String { "\(sources)/Info.plist" }
    var xcodeEntitlementsPath: String { "\(sources)/\(name).entitlements" }
    var xtoolEntitlementsPath: String { "\(sources)/\(name).xtool.entitlements" }

    /// The same Info.plist for both builds, with literal values: xtool doesn't
    /// expand Xcode's build variables.
    func infoPlist() throws -> Data {
        var info = info.mapValues(\.object)
        info["CFBundleName"] = name
        info["CFBundleExecutable"] = name
        info["CFBundleIdentifier"] = bundleID
        info["CFBundleShortVersionString"] = version
        info["CFBundleVersion"] = build
        return try plist(info)
    }

    func xcodeEntitlements() throws -> Data { try plist(teamEntitlements.mapValues(\.object)) }

    /// xtool builds only the Mac app, ad-hoc signed: the sandbox entitlements,
    /// none that need a team.
    func xtoolEntitlements() throws -> Data {
        try plist(Dictionary(uniqueKeysWithValues: sandbox.map { ($0.key, true as Any) }))
    }

    private func relative(_ path: String) -> String {
        path.hasPrefix(sources + "/") ? String(path.dropFirst(sources.count + 1)) : path
    }

    func xtoolYAML() -> String {
        """
        # \(marker).
        # Builds \(name).app with xtool (https://xtool.sh) rather than Xcode:
        #   xtool dev build --triple arm64-apple-macosx
        version: 1
        bundleID: \(bundleID)
        product: \(name)
        infoPath: \(infoPath)
        iconPath: \(icon)
        entitlementsPath: \(xtoolEntitlementsPath)
        resources:
        \(resources.map { "  - \($0)" }.joined(separator: "\n"))

        """
    }

    /// The Xcode app target, for project.yml's marked region.
    func projectTarget() -> String {
        let iconName = URL(fileURLWithPath: icon).deletingPathExtension().lastPathComponent
        var settings: [(String, String)] = [
            ("PRODUCT_NAME", name),
            ("PRODUCT_BUNDLE_IDENTIFIER", bundleID),
            ("MARKETING_VERSION", version),
            ("CURRENT_PROJECT_VERSION", "\"\(build)\""),
            ("INFOPLIST_FILE", infoPath),
            ("GENERATE_INFOPLIST_FILE", "NO"),
            ("CODE_SIGN_ENTITLEMENTS", xcodeEntitlementsPath),
            ("DEVELOPMENT_TEAM", developmentTeam),
            ("ASSETCATALOG_COMPILER_APPICON_NAME", iconName),
        ]
        settings += sandbox.map { ($0.xcodeSetting, "YES") }
        settings += xcodeSettings
        return """
          # BEGIN \(marker).
          \(xcodeTarget):
            type: application
            platform: iOS
            sources:
              - path: \(sources)
                excludes:
                  - \(relative(icon))
                  - \(relative(xtoolEntitlementsPath))
              - path: \(icon)
            dependencies:
              - package: HummingbirdPackage
                product: HummingbirdKit
              - package: SwiftOpenUI
                product: SwiftOpenUI
            settings:
              base:
        \(settings.map { "        \($0.0): \($0.1)" }.joined(separator: "\n"))
          # END GENERATED app target.

        """
    }

    /// The package product xtool builds, for Package.swift's marked region.
    func packageSection() -> String {
        let excluded = [infoPath, icon, xcodeEntitlementsPath, xtoolEntitlementsPath] + resources
        return """
        // BEGIN \(marker).
        // The app for xtool (xtool.yml): the product is the app's name, as
        // xtool names the bundle and executable after it.
        #if os(macOS)
        package.products.append(.library(name: "\(name)", targets: ["\(name)App"]))
        package.targets.append(
            .target(
                name: "\(name)App",
                dependencies: [
                    "HummingbirdKit",
                    .product(name: "SwiftOpenUI", package: "SwiftOpenUI"),
                ],
                path: "\(sources)",
                // Packed by xtool from xtool.yml rather than built as sources.
                exclude: [\(excluded.map { "\"\(relative($0))\"" }.joined(separator: ", "))]
            )
        )
        #endif
        // END GENERATED app product.

        """
    }

    private func plist(_ object: Any) throws -> Data {
        try PropertyListSerialization.data(fromPropertyList: object, format: .xml, options: 0)
    }
}

// MARK: - Writing and checking

/// Replaces the text between a line containing `begin` and one containing
/// `end` (both included) with `replacement`.
func replacingRegion(in text: String, begin: String, end: String, with replacement: String) throws -> String {
    var lines = text.components(separatedBy: "\n")
    guard let start = lines.firstIndex(where: { $0.contains(begin) }),
          let stop = lines[start...].firstIndex(where: { $0.contains(end) }) else {
        throw GenerationError.missingRegion(begin)
    }
    lines.replaceSubrange(start...stop, with: replacement.components(separatedBy: "\n").dropLast())
    return lines.joined(separator: "\n")
}

enum GenerationError: Error, CustomStringConvertible {
    case missingRegion(String)
    case nameClash(target: String, product: String)
    case staleReference(String, target: String)

    var description: String {
        switch self {
        case .missingRegion(let begin): "no generated region starting with \"\(begin)\""
        case .nameClash(let target, let product):
            "project.yml's target \"\(target)\" has the name of \(product): xcodebuild would build that instead of the target (for the app under test, UI tests couldn't start)"
        case .staleReference(let reference, let target):
            "project.yml refers to the app target as \"\(reference)\"; the target is \"\(target)\""
        }
    }
}

// MARK: - Name checks

/// The keys of a top-level project.yml section (`targets:`, `packages:`...).
func sectionKeys(_ section: String, in project: String) -> [String] {
    var keys: [String] = [], inside = false
    for line in project.components(separatedBy: "\n") {
        if !line.hasPrefix(" "), !line.isEmpty { inside = line == "\(section):"; continue }
        guard inside, line.hasPrefix("  "), !line.hasPrefix("   "), line.hasSuffix(":"),
              !line.trimmingCharacters(in: .whitespaces).hasPrefix("#") else { continue }
        keys.append(String(line.dropFirst(2).dropLast()))
    }
    return keys
}

/// The library and executable products a package manifest declares.
func productNames(in manifest: String) -> [String] {
    let pattern = /\.(?:library|executable)\(\s*name:\s*"([^"]+)"/
    return manifest.matches(of: pattern).map { String($0.output.1) }
}

/// Refuses names xcodebuild would confuse: a project target with the name of
/// a package product or of a package itself (xcodebuild builds the product in
/// its place, so for the app target the app under test is a library and UI
/// tests can't start), and any reference to the app target by the app's name.
func checkNames(project: String, package: String) throws {
    // Each name xcodebuild could resolve to a package, and what it is.
    var packageNames: [String: String] = [:]
    for product in productNames(in: package) + [manifest.name] {
        packageNames[product] = "the package product \(product)"
    }
    for key in sectionKeys("packages", in: project) {
        packageNames[key] = "the package \(key)"
        // The package's own products: `path:` on the line after its key.
        let lines = project.components(separatedBy: "\n")
        if let index = lines.firstIndex(of: "  \(key):"), lines.indices.contains(index + 1),
           let path = lines[index + 1].split(separator: "path:").last?.trimmingCharacters(in: .whitespaces),
           let text = try? String(contentsOf: file(path).appendingPathComponent("Package.swift"), encoding: .utf8) {
            for product in productNames(in: text) { packageNames[product] = "the package product \(product)" }
        }
    }
    for target in sectionKeys("targets", in: project) + sectionKeys("aggregateTargets", in: project) {
        if let package = packageNames[target] { throw GenerationError.nameClash(target: target, product: package) }
    }
    for reference in ["- target: \(manifest.name)\n", "TEST_TARGET_NAME: \(manifest.name)\n",
                      "        \(manifest.name): all\n"] where project.contains(reference) {
        throw GenerationError.staleReference(reference.trimmingCharacters(in: .whitespacesAndNewlines),
                                             target: manifest.xcodeTarget)
    }
}

let root = URL(fileURLWithPath: CommandLine.arguments.count > 1 && !CommandLine.arguments[1].hasPrefix("-")
               ? CommandLine.arguments[1] : FileManager.default.currentDirectoryPath)
let checking = CommandLine.arguments.contains("--check")

func file(_ path: String) -> URL { root.appendingPathComponent(path) }
func current(_ path: String) -> Data? { try? Data(contentsOf: file(path)) }

do {
    let project = try String(contentsOf: file("project.yml"), encoding: .utf8)
    let package = try String(contentsOf: file("Package.swift"), encoding: .utf8)
    let newProject = try replacingRegion(in: project, begin: "# BEGIN GENERATED", end: "# END GENERATED app target",
                                         with: manifest.projectTarget())
    let newPackage = try replacingRegion(in: package, begin: "// BEGIN GENERATED", end: "// END GENERATED app product",
                                         with: manifest.packageSection())
    try checkNames(project: newProject, package: newPackage)
    let outputs: [(String, Data)] = [
        (manifest.infoPath, try manifest.infoPlist()),
        (manifest.xcodeEntitlementsPath, try manifest.xcodeEntitlements()),
        (manifest.xtoolEntitlementsPath, try manifest.xtoolEntitlements()),
        ("xtool.yml", Data(manifest.xtoolYAML().utf8)),
        ("project.yml", Data(newProject.utf8)),
        ("Package.swift", Data(newPackage.utf8)),
    ]
    var stale: [String] = []
    for (path, data) in outputs where current(path) != data {
        if checking { stale.append(path) } else { try data.write(to: file(path)) }
    }
    if !stale.isEmpty {
        FileHandle.standardError.write(Data("""
            error: out of date with Apps/AppManifest.swift: \(stale.joined(separator: ", "))
            Run scripts/generate-app and commit the result.

            """.utf8))
        exit(1)
    }
} catch {
    FileHandle.standardError.write(Data("error: \(error)\n".utf8))
    exit(1)
}
